class Solution {
    public int minimumTeachings(int n,int[][] languages,int[][] friendships){
        List<Set<Integer>> known=new ArrayList<>();
        for(int[] user:languages){
            Set<Integer> set=new HashSet<>();
            for(int language:user)set.add(language);
            known.add(set);
        }
        Set<Integer> candidates=new HashSet<>();
        for(int[] friendship:friendships){
            Set<Integer> first=known.get(friendship[0]-1),second=known.get(friendship[1]-1);
            boolean share=false;
            for(int language:first)if(second.contains(language)){
                share=true;
                break;
            }
            if(!share){
                candidates.add(friendship[0]-1);
                candidates.add(friendship[1]-1);
            }
        }
        int answer=candidates.size();
        for(int language=1;language<=n;language++){
            int teach=0;
            for(int user:candidates)if(!known.get(user).contains(language))teach++;
            answer=Math.min(answer,teach);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun minimumTeachings(n:Int,languages:Array<IntArray>,friendships:Array<IntArray>):Int{
        val known=languages.map{
            it.toSet()
        };
        val candidates=mutableSetOf<Int>();
        for(friendship in friendships){
            val first=friendship[0]-1;
            val second=friendship[1]-1;
            if(known[first].intersect(known[second]).isEmpty()){
                candidates.add(first);
                candidates.add(second)
            }
        };
        var answer=candidates.size;
        for(language in 1..n)answer=minOf(answer,candidates.count{
            language !in known[it]
        });
        return answer
    }
}

